using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Linq;using System.Windows.Forms;
namespace IDSketcher {
partial class Canvas {
 public void ApplyVectorColour(){if(Doc==null||!Doc.Selected.IsVector||Doc.Selected.IsLocked)return;var targets=Doc.Selected.Vectors.Where(p=>selectedPaths.Contains(p)&&p.Colour.ToArgb()!=Ink.ToArgb()).ToList();if(targets.Count==0)return;if(BeforeStroke!=null)BeforeStroke();foreach(var shape in targets)shape.Colour=Ink;Doc.Selected.InvalidateVectors();if(AfterStroke!=null)AfterStroke();Invalidate();}
}
partial class VectorShape {
 GraphicsPath PolygonTaperPath(){var outline=new GraphicsPath(FillMode.Winding);if(Points.Count<2)return outline;for(int i=0;i<Points.Count;i++){int next=(i+1)%Points.Count;if(StrokeSession.Distance(Points[i],Points[next])<.001f)continue;var edge=new VectorShape{Kind="Line",Width=Width,Taper=Taper,Points=new List<PointF>{Points[i],Points[next]}};if(Handles.Count>0){edge.Handles[0]=(PointF[])PointHandles(i).Clone();edge.Handles[1]=(PointF[])PointHandles(next).Clone();}using(var path=edge.TaperPath())if(path.PointCount>0)outline.AddPath(path,false);}return outline;}
}
partial class Studio {
 public void TestVersion35(){if(mode.Items.Contains("CMYK")||mode.Items.Count!=3)throw new Exception("Colour options");SetDocument(new Document("A4",100),null);AddTypedLayer(true);canvas.Zoom=1;canvas.Offset=PointF.Empty;vectorMode.SelectedItem="Line";canvas.VectorWidth=10;canvas.VectorOpacity=1;canvas.VectorTaper=0;canvas.TestDrag(new Point(100,100),new Point(300,100));canvas.TestDrag(new Point(100,200),new Point(300,200));canvas.SelectPathsInBox(new RectangleF(50,50,300,200),Keys.None);canvas.Doc.Selected.Rendered();mode.SelectedItem="RGB";colourEntry.Text="240, 30, 80";int history=undo.Count;colourEntry.Parent.Controls.OfType<Button>().First(b=>b.Text=="Apply").PerformClick();if(canvas.Doc.Selected.Vectors.Any(p=>p.Colour!=Color.FromArgb(240,30,80))||undo.Count!=history+1)throw new Exception("Colour Apply to selected paths");if(canvas.Doc.Selected.Rendered().GetPixel(150,100).R!=240)throw new Exception("Colour cache invalidation");Travel(undo,redo);Travel(redo,undo);if(canvas.Doc.Selected.Vectors.Any(p=>p.Colour!=Color.FromArgb(240,30,80)))throw new Exception("Colour redo");canvas.SelectPathsInBox(new RectangleF(50,50,300,200),Keys.None);canvas.Doc.Selected.Locked=true;canvas.Ink=Color.Blue;canvas.ApplyVectorColour();if(canvas.Doc.Selected.Vectors[0].Colour==Color.Blue)throw new Exception("Locked colour");canvas.Doc.Selected.Locked=false;
 var square=new VectorShape{Kind="Polygon",Width=20,Taper=100,Points=new List<PointF>{new PointF(100,100),new PointF(200,100),new PointF(200,200),new PointF(100,200)}};using(var path=square.TaperPath()){foreach(var p in new[]{new PointF(150,108),new PointF(192,150),new PointF(150,192),new PointF(108,150)})if(!path.IsVisible(p))throw new Exception("Every polygon edge taper midpoint");if(path.IsVisible(new PointF(103,108)))throw new Exception("Polygon corner must taper");}square.SetPointHandle(0,1,new PointF(125,70));using(var path=square.TaperPath())if(path.PointCount==0)throw new Exception("Curved polygon taper");square.Filled=true;if(square.CanTaper)throw new Exception("Filled polygon taper");dirty=false;}
}
}
